import{_ as r,c as s,o as a,ah as t,j as e,a as i}from"./chunks/framework.CAZQ2vdu.js";const d="/Qonnectra-docs/pr-17/images/manual/teil-a/records.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/records_search.jpg",c="/Qonnectra-docs/pr-17/images/manual/teil-a/records_new.jpg",u="/Qonnectra-docs/pr-17/images/manual/teil-a/records_inquiry.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/records_inquiry_tools.jpg",h="/Qonnectra-docs/pr-17/videos/records_inquiry_draw.webm",b="/Qonnectra-docs/pr-17/images/manual/teil-a/records_export.jpg",g="/Qonnectra-docs/pr-17/images/manual/teil-a/records_detail.jpg",v=JSON.parse('{"title":"8. Leitungsauskunft","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/08-leitungsauskunft.md","filePath":"manual/teil-a-anwenderhandbuch/08-leitungsauskunft.md"}'),m={name:"manual/teil-a-anwenderhandbuch/08-leitungsauskunft.md"};function p(f,n,k,A,w,S){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="_8-leitungsauskunft" tabindex="-1">8. Leitungsauskunft <a class="header-anchor" href="#_8-leitungsauskunft" aria-label="Permalink to &quot;8. Leitungsauskunft&quot;">​</a></h1><p>Die <strong>Leitungsauskunft</strong> beantwortet Anfragen zum Leitungsbestand: Ein Bauunternehmen, ein Planungsbüro oder eine Behörde will vor Arbeiten wissen, welche Leitungen in einem bestimmten Bereich liegen. Qonnectra führt jede Anfrage als eigenen Datensatz mit den Angaben zur anfragenden Stelle, lässt Sie dazu einen oder mehrere <strong>Auskunftsbereiche</strong> in die Karte zeichnen und gibt alles, was darin liegt, als ZIP-Archiv aus. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Funktionen“ durch Klicken auf den Menüpunkt „Leitungsauskunft“.</p><p><img src="'+d+'" alt="Screenshot Leitungsauskunft mit der Tabelle der Auskünfte" data-zoomable="true"></p><p>Eine Auskunft entsteht in drei Schritten, die in dieser Reihenfolge aufeinander aufbauen: Datensatz anlegen, Bereiche zeichnen, exportieren. Der Datensatz ohne Bereich lässt sich nicht exportieren – der Button dafür erscheint erst, wenn mindestens ein Bereich gezeichnet ist.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Angaben zur anfragenden Stelle sind Kontaktdaten und damit personenbezogen. Erfassen Sie nur, was Sie für die Bearbeitung brauchen, und löschen Sie den Datensatz, wenn die Anfrage abgeschlossen und die Aufbewahrungsfrist abgelaufen ist.</p></div><h2 id="_8-1-auskunfte-suchen-und-filtern" tabindex="-1">8.1 Auskünfte suchen und filtern <a class="header-anchor" href="#_8-1-auskunfte-suchen-und-filtern" aria-label="Permalink to &quot;8.1 Auskünfte suchen und filtern&quot;">​</a></h2><p>Die Tabelle listet die Auskünfte mit den Spalten „Projekt“, „Art der Arbeit“, „Grund der Anfrage“, „Organisation“, „Name“, „Erstellt“ und „Geändert“ auf, die jüngste zuerst. Sortierung, Spaltenfilter und Seitenwechsel funktionieren wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel">Tabellen</a> beschrieben; ein Klick auf eine Zeile öffnet den Datensatz auf einer eigenen Seite.</p><p><img src="'+l+'" alt="Screenshot Leitungsauskunft mit Hervorhebung des Suchfeldes über der Tabelle und der Filterfelder unter den Spaltenüberschriften" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Diese Tabelle ist die einzige Bestandsliste in Qonnectra, die <strong>nicht</strong> auf das gewählte Projekt beschränkt ist: Sie enthält die Auskünfte aller Projekte, und es gibt keine Schaltfläche, mit der Sie das umstellen könnten. Achten Sie deshalb auf die Spalte „Projekt“, und grenzen Sie die Tabelle über deren Filterfeld ein, wenn Sie nur die Anfragen eines Projekts sehen wollen.</p></div><p>Das Suchfeld über der Tabelle durchsucht „Organisation“, „Name“, „Art der Arbeit“, „Grund der Anfrage“ und den Projektnamen. Gesucht wird nach einem enthaltenen Textstück und ohne Rücksicht auf Groß- und Kleinschreibung; anders als die Adresssuche der Nachverdichtung verzeiht diese Suche keine Tippfehler.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Telefon- und Mobilnummern werden nicht durchsucht. Eine Anfrage, von der Sie nur die Rufnummer haben, finden Sie über die Suche nicht – die Nummern stehen ausschließlich im Datensatz selbst.</p></div><p>Die Nachschlagelisten für „Art der Arbeit“ und „Grund der Anfrage“ pflegt die Administration, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>. Sie gelten instanzweit und nicht je Projekt.</p><h2 id="_8-2-neue-auskunft-anlegen-art-der-arbeit-grund-kontaktdaten" tabindex="-1">8.2 Neue Auskunft anlegen: Art der Arbeit, Grund, Kontaktdaten <a class="header-anchor" href="#_8-2-neue-auskunft-anlegen-art-der-arbeit-grund-kontaktdaten" aria-label="Permalink to &quot;8.2 Neue Auskunft anlegen: Art der Arbeit, Grund, Kontaktdaten&quot;">​</a></h2><p>Der Button „+ Erstellen“ über der Tabelle öffnet das Formular für eine neue Auskunft. Es besteht aus drei Abschnitten:</p><ul><li><strong>„Projekt“</strong> – „Projekt“ (Pflichtfeld), „Art der Arbeit“ und „Grund der Anfrage“. Die beiden Kombinationsfelder bedienen Sie wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-2-auswahllisten-und-kombinationsfelder">Auswahllisten und Kombinationsfelder</a> beschrieben.</li><li><strong>„Organisation“</strong> – „Organisation“ und „Name“, also die anfragende Stelle und die Person, die dort zuständig ist.</li><li><strong>„Telefon“</strong> – „Telefon“ und „Mobil“.</li></ul><p><img src="'+c+'" alt="Screenshot Formular für eine neue Auskunft mit den Abschnitten „Projekt“, „Organisation“ und „Telefon“" data-zoomable="true"></p><p>„Erstellen“ legt den Datensatz an, meldet „Leitungsauskunft-Datensatz erfolgreich erstellt“ und wechselt direkt in dessen Detailansicht. Über „Zurück“ verlassen Sie das Formular ohne zu speichern.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Feld „Projekt“ ist nicht bearbeitbar: Eine neue Auskunft entsteht immer im Projekt, das oben links in der Kopfzeile gewählt ist, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>. Wechseln Sie das Projekt, bevor Sie das Formular öffnen, wenn die Anfrage einen anderen Bestand betrifft. Nachträglich lässt sich das Projekt nicht mehr ändern.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Außer dem Projekt ist kein Feld ein Pflichtfeld. „Erstellen“ legt den Datensatz auch dann an, wenn Sie nichts ausgefüllt haben – in der Tabelle steht er danach als Zeile, in der nur Projekt und Zeitstempel gefüllt sind.</p></div><h2 id="_8-3-auskunftsbereiche-zeichnen-umbenennen-und-loschen" tabindex="-1">8.3 Auskunftsbereiche zeichnen, umbenennen und löschen <a class="header-anchor" href="#_8-3-auskunftsbereiche-zeichnen-umbenennen-und-loschen" aria-label="Permalink to &quot;8.3 Auskunftsbereiche zeichnen, umbenennen und löschen&quot;">​</a></h2><p>In der Detailansicht führt der Button „Neue Auskunft“ in die Karte, in der Sie die Bereiche der Anfrage zeichnen. Sobald mindestens ein Bereich vorhanden ist, heißt derselbe Button „Auskunft bearbeiten“.</p><p>Solange kein Bereich gezeichnet ist, steht am unteren Rand der Karte der Hinweis „Zeichne Polygone auf der Karte, um Bereiche für die Auskunft auszuwählen.“ Die Karte selbst verhält sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben.</p><p><img src="'+u+'" alt="Screenshot Auskunftsabfrage mit einem gezeichneten Auskunftsbereich und den darin hervorgehobenen Objekten" data-zoomable="true"></p><p>Oben links unter der Suche liegen die beiden Werkzeuge, rechts die Liste „Auskunftsbereiche“.</p><p><img src="'+o+'" alt="Screenshot Auskunftsabfrage mit Hervorhebung der Werkzeuge oben links und der Liste „Auskunftsbereiche“ rechts" data-zoomable="true"></p><p><strong>Bereich zeichnen</strong></p><ol><li>Klicken Sie auf „Polygon zeichnen“. Das Werkzeug ist damit <strong>eingeschaltet</strong>; die Schaltfläche heißt jetzt „Zeichnen beenden“.</li><li>Klicken Sie die Eckpunkte des Bereichs nacheinander in die Karte.</li><li>Ein Doppelklick schließt das Polygon.</li></ol><p>Der Bereich wird sofort gespeichert, gemeldet durch „Auskunftspolygon gespeichert.“; einen Button zum Speichern gibt es nicht. Das Werkzeug bleibt eingeschaltet, Sie können also gleich den nächsten Bereich zeichnen. Über „Zeichnen beenden“ schalten Sie es wieder aus.</p>',28),e("p",null,[e("video",{src:h,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/records_inquiry_draw.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),t('<p>Alles, was innerhalb der Bereiche liegt, hebt die Karte orange hervor: Trassen, Netzknoten, Adressen und Gebiete. Daran lesen Sie ab, was der Export enthalten wird, noch bevor Sie ihn auslösen.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Projektgebiet, in dem Sie zeichnen, wird dabei als Ganzes hervorgehoben, auch wenn Ihr Bereich nur einen kleinen Teil davon abdeckt: Seine Fläche schneidet den Bereich, und hervorgehoben wird immer das ganze Objekt. Die orange Fläche über der halben Karte ist deshalb kein Zeichen dafür, dass Sie zu groß gezeichnet haben. Blenden Sie den Layer „Gebiet“ in der Legende aus, wenn Sie prüfen wollen, welche Trassen und Adressen der Bereich wirklich trifft.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Hervorhebung folgt der Legende: Was Sie dort ausblenden, wird auch nicht hervorgehoben – der Export enthält es trotzdem. Umgekehrt zeigt die Karte keine Rohre, Mikrorohre und Kabel, weil diese keine eigene Geometrie haben; im Export sind sie enthalten, siehe Abschnitt <a href="#_8-4-auskunft-exportieren">Auskunft exportieren</a>.</p></div><p><strong>Bereich umbenennen</strong></p><p>Jeder Bereich bekommt beim Zeichnen von selbst einen Namen und steht damit in der Liste „Auskunftsbereiche“ und als Beschriftung am Polygon in der Karte. Zum Umbenennen klicken Sie in das Eingabefeld des Bereichs, geben einen Namen ein und drücken Enter oder klicken neben das Feld; Qonnectra meldet „Auskunftspolygon umbenannt.“. Mit Escape verwerfen Sie die Eingabe.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die vergebenen Namen lauten „Area 1“, „Area 2“ und so weiter – englisch, unabhängig von der Sprache der Oberfläche. Sie sagen nichts über die Anfrage; benennen Sie die Bereiche um, sobald ein Datensatz mehr als einen davon hat. Die Nummer richtet sich nach dem höchsten bereits vergebenen „Area N“ des Datensatzes und wird nach dem Löschen eines Bereichs nicht erneut verwendet.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Beschriftung am Polygon erscheint erst ab einer ausreichenden Zoomstufe. Ist die Karte weit herausgezoomt, sehen Sie nur die Umrisse – welcher Umriss zu welchem Eintrag der Liste gehört, ist dann nicht zu erkennen.</p></div><p><strong>Bereich ändern</strong></p><p>Sobald ein Bereich vorhanden ist, erscheint unter dem Zeichenwerkzeug ein zweites: „Polygone bearbeiten“. Bei eingeschaltetem Werkzeug ziehen Sie einen Eckpunkt an eine neue Stelle oder greifen eine Kante zwischen zwei Eckpunkten und ziehen daraus einen neuen Eckpunkt heraus. Beim Loslassen wird die Änderung gespeichert („Auskunftspolygon aktualisiert.“). „Bearbeiten beenden“ schaltet das Werkzeug aus.</p><p>Die beiden Werkzeuge schließen sich gegenseitig aus: Das Einschalten des einen schaltet das andere ab.</p><p><strong>Bereich löschen</strong></p><p>Das Papierkorbsymbol rechts neben dem Namen entfernt den Bereich.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Das Löschen erfolgt ohne Rückfrage und ist nicht widerrufbar. Der Bereich verschwindet unmittelbar aus Karte und Liste; die gezeichnete Geometrie ist damit verloren und muss neu gezeichnet werden.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Löschen setzt das Recht dazu voraus. Fehlt es Ihrem Konto, bleibt der Bereich stehen und Qonnectra meldet „Sie sind nicht berechtigt, diese Aktion durchzuführen.“ – Zeichnen, Ändern und Umbenennen sind davon nicht betroffen. Welche Rolle was darf, beschreibt Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</p></div><p>Über „Zurück“ gelangen Sie in die Detailansicht des Datensatzes.</p><h2 id="_8-4-auskunft-exportieren" tabindex="-1">8.4 Auskunft exportieren <a class="header-anchor" href="#_8-4-auskunft-exportieren" aria-label="Permalink to &quot;8.4 Auskunft exportieren&quot;">​</a></h2><p>Sobald der Datensatz mindestens einen Auskunftsbereich hat, steht in der Detailansicht der Button „Exportieren“. Er erzeugt das ZIP-Archiv, der Browser fragt nach dem Speicherort, und Qonnectra meldet „Auskunftsdaten erfolgreich exportiert.“</p><p><img src="'+b+'" alt="Screenshot Detailansicht einer Auskunft mit Hervorhebung des Buttons „Exportieren“" data-zoomable="true"></p><p>Das Archiv heißt <code>inquiry-export-&lt;UUID&gt;.zip</code> und enthält:</p><ul><li>einen Ordner <code>layers</code> mit je einer GeoJSON-Datei für <code>trenches</code>, <code>nodes</code>, <code>addresses</code>, <code>conduits</code>, <code>cables</code>, <code>areas</code> und <code>microducts</code>,</li><li>die QGIS-Layerdatei <code>inquiry_export.qlr</code>, die alle enthaltenen Layer auf einmal öffnet,</li><li>einen Ordner <code>files</code> mit den Anhängen der enthaltenen Objekte, sofern es welche gibt.</li></ul><p>Enthalten ist, was innerhalb der Bereiche des Datensatzes liegt; bei mehreren Bereichen deren Gesamtfläche. Rohre, Mikrorohre und Kabel haben keine eigene Geometrie – sie kommen über die Trassen hinein, die sie führen, und tragen deshalb im Export die Geometrie dieser Trassen sowie die Kennungen der Trassen bzw. Rohre, in denen sie liegen.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Feldnamen im Export sind englisch (<code>id_trench</code>, <code>construction_type</code>, <code>status</code>), die Werte darin die deutschen Bezeichnungen aus den Stammdaten („unbefestigt“, „klassischer Tiefbau“). Einen Überblick über alle Exportformate von Qonnectra gibt Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Layer ohne Inhalt lässt der Export weg. Fehlt eine Datei im Archiv, liegt in den Bereichen kein Objekt dieser Art – das ist kein Fehler des Exports. Liegt in den Bereichen überhaupt nichts, fehlt auch die <code>.qlr</code>-Datei.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Dateiname enthält die technische Kennung des Datensatzes und nicht den Namen der anfragenden Stelle. Benennen Sie die Datei beim Speichern um, wenn Sie sie ablegen oder weitergeben – aus dem Archiv selbst geht nicht hervor, zu welcher Anfrage es gehört.</p></div><p>Der Export ist eine Momentaufnahme und wird nirgends gespeichert. Ändert sich der Netzbestand, erzeugen Sie das Archiv neu; gehört es dauerhaft zur Anfrage, legen Sie es außerhalb von Qonnectra ab.</p><h2 id="_8-5-auskunft-andern-und-loschen" tabindex="-1">8.5 Auskunft ändern und löschen <a class="header-anchor" href="#_8-5-auskunft-andern-und-loschen" aria-label="Permalink to &quot;8.5 Auskunft ändern und löschen&quot;">​</a></h2><p>In der Detailansicht sind alle Felder bis auf „Projekt“ bearbeitbar. „Speichern“ übernimmt die Änderungen und meldet „Leitungsauskunft-Datensatz erfolgreich aktualisiert“.</p><p><img src="'+g+'" alt="Screenshot Detailansicht einer Auskunft mit Hervorhebung der Buttons „Löschen“ und „Speichern“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die beiden Kombinationsfelder „Art der Arbeit“ und „Grund der Anfrage“ zeigen in der Detailansicht „-“, auch wenn der Datensatz Werte enthält. Was tatsächlich gespeichert ist, lesen Sie in den entsprechenden Spalten der Tabelle ab. Die Werte gehen dadurch nicht verloren: „Speichern“ behält sie, solange Sie die Felder nicht anfassen. Wählen Sie einen Eintrag aus, ersetzt er den bisherigen Wert.</p></div><p>„Löschen“ fragt mit „Löschen bestätigen“ nach; erst der Klick auf „Löschen“ in diesem Fenster führt es aus. Danach zeigt Qonnectra wieder die Tabelle.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Mit dem Datensatz verschwinden alle seine Auskunftsbereiche. Ein bereits erzeugtes ZIP-Archiv bleibt davon unberührt, weil es außerhalb von Qonnectra liegt – die Bereiche selbst lassen sich daraus aber nicht wiederherstellen.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Auch für den Datensatz gilt: Ohne das Recht zum Löschen bleibt er nach der Bestätigung stehen, und Qonnectra meldet „Sie sind nicht berechtigt, diese Aktion durchzuführen.“ Ändern und Speichern sind davon nicht betroffen.</p></div>',32)])])}const _=r(m,[["render",p]]);export{v as __pageData,_ as default};
